 80	fn linear(c: u32, shift: u32) -> f64 { let v = ((c >> shift) & 255) as f64 / 255.0; if v <= 0.04045 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) } }
 81	fn luminance(c: u32) -> f64 { 0.2126*linear(c,24) + 0.7152*linear(c,16) + 0.0722*linear(c,8) }
 82	fn contrast(a: u32,b: u32) -> f64 { let (x,y)=(luminance(a),luminance(b)); (x.max(y)+0.05)/(x.min(y)+0.05) }
 83	fn accent_candidate(source: u32, lighten: bool, percent: u32) -> u32 {
 84	    let mut out=0; for shift in [8,16,24] { let channel=(source>>shift)&255; let target=if lighten {255} else {0}; let adjusted=(channel*(100-percent)+target*percent+50)/100; out|=adjusted<<shift; } out|255
 85	}
