 87	pub fn theme_tokens_accented(theme: Theme, high_contrast: bool, system_accent_srgb: u32) -> Tokens {
 88	    let mut tokens=theme_tokens(theme,high_contrast);
 89	    if system_accent_srgb == 0 || system_accent_srgb & 255 == 0 { return tokens; }
 90	    let required=if high_contrast {4.5} else {3.0}; let lighten=theme==Theme::Dark;
 91	    let mut best=system_accent_srgb|255; let mut best_score=0.0;
 92	    for amount in 0..=100 { let candidate=accent_candidate(system_accent_srgb,lighten,amount);
 93	        let score=contrast(candidate,tokens.panel).min(contrast(candidate,tokens.panel_raised));
 94	        if score>best_score {best=candidate;best_score=score;} if score>=required {best=candidate;break;} }
 95	    tokens.accent=best; tokens.selection_edge=best; tokens.focus_ring=best;
 96	    let percent=if high_contrast {20} else {14}; let mut blended=255;
 97	    for shift in [8,16,24] { let back=(tokens.panel>>shift)&255; let front=(best>>shift)&255;
 98	        blended|=((back*(100-percent)+front*percent+50)/100)<<shift; }
 99	    tokens.selection_fill=blended; tokens
100	}
