  6	pub const MAX_NODES: usize=128; pub const MAX_DEPTH: usize=24; pub const ROOT_ID: u32=1;
  7	pub const MAX_TEXT_BYTES: usize=64; pub const MAX_TEXT_TOTAL_BYTES: usize=1024*1024; pub const MAX_COMMANDS: usize=64;
  8	const STATE_DISABLED:u32=1; const STATE_CHECKED:u32=2; const STATE_FOCUSED:u32=4;
  9	const NO_ICON:u32=54;
