 19	impl NodeSpec { pub fn new(id:u32,parent_id:u32)->Self { Self{id,parent_id,axis:Axis::Overlay,preferred_width:0,preferred_height:0,padding:0,gap:0,color:0,role:Role::None,label:String::new(),value:String::new(),state:0,command_id:0,icon_kind:0,widget_kind:0} } }
 20	#[derive(Debug,Clone,PartialEq,Eq)] pub struct Node {
