 22	}
 23	#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum TreeError { InvalidInput,Capacity,DuplicateId,MissingParent,InvalidUtf8,TextLimit,Layout,Allocation,NotLaidOut }
 24	#[derive(Debug,Clone,PartialEq)] pub struct Tree {
 25	    pub nodes:Vec<Node>,pub text_bytes_used:usize,pub laid_out:bool,pub focused_id:u32,pub theme:Theme,
 26	    pub increased_contrast:bool,pub semantic_style:bool,pub backing_scale:f64,pub tokens:Tokens,
 27	}
