 89	static double ui_linear_channel(uint32_t color, uint32_t shift)
 90	{
 91	    double channel = (double)((color >> shift) & 255U) / 255.0;
 92	    return channel <= 0.04045 ? channel / 12.92 :
 93	        pow((channel + 0.055) / 1.055, 2.4);
 94	}
 95	
 96	static double ui_luminance(uint32_t color)
 97	{
 98	    return 0.2126 * ui_linear_channel(color, 24U) +
 99	        0.7152 * ui_linear_channel(color, 16U) +
100	        0.0722 * ui_linear_channel(color, 8U);
101	}
102	
103	static double ui_contrast(uint32_t first, uint32_t second)
104	{
105	    double a = ui_luminance(first), b = ui_luminance(second);
106	    return (fmax(a, b) + 0.05) / (fmin(a, b) + 0.05);
107	}
