109	static uint32_t ui_accent_candidate(uint32_t source, bool lighten,
110	                                    uint32_t percent)
111	{
112	    uint32_t output = 0U;
113	    for (uint32_t shift = 8U; shift <= 24U; shift += 8U) {
114	        uint32_t channel = (source >> shift) & 255U;
115	        uint32_t target = lighten ? 255U : 0U;
116	        uint32_t adjusted = (channel * (100U - percent) + target * percent + 50U) / 100U;
117	        output |= adjusted << shift;
118	    }
119	    return output | 255U;
120	}
121	
122	static uint32_t ui_accent_with_contrast(uint32_t source, ui_theme theme,
123	                                        bool increased_contrast,
124	                                        const ui_tokens *tokens)
125	{
126	    double required = increased_contrast ? 4.5 : 3.0;
127	    bool lighten = theme == UI_THEME_DARK;
128	    uint32_t best = source | 255U;
129	    double best_contrast = 0.0;
130	    for (uint32_t amount = 0U; amount <= 100U; ++amount) {
131	        uint32_t candidate = ui_accent_candidate(source, lighten, amount);
132	        double against_panel = ui_contrast(candidate, tokens->panel);
133	        double against_raised = ui_contrast(candidate, tokens->panel_raised);
134	        double score = fmin(against_panel, against_raised);
135	        if (score > best_contrast) {
136	            best = candidate;
137	            best_contrast = score;
138	        }
139	        if (score >= required) return candidate;
140	    }
141	    return best;
142	}
143	
144	static uint32_t ui_blend_opaque(uint32_t background, uint32_t foreground,
145	                                uint32_t opacity_percent)
146	{
147	    uint32_t result = 255U;
148	    for (uint32_t shift = 8U; shift <= 24U; shift += 8U) {
149	        uint32_t back = (background >> shift) & 255U;
150	        uint32_t front = (foreground >> shift) & 255U;
151	        uint32_t channel = (back * (100U - opacity_percent) +
152	            front * opacity_percent + 50U) / 100U;
153	        result |= channel << shift;
154	    }
155	    return result;
156	}
