158	ui_tokens ui_theme_tokens_accented(ui_theme theme, bool increased_contrast,
159	                                   uint32_t system_accent_srgb)
160	{
161	    ui_tokens tokens = ui_theme_tokens(theme, increased_contrast);
162	    if (system_accent_srgb == 0U || (system_accent_srgb & 255U) == 0U)
163	        return tokens;
164	    uint32_t accent = ui_accent_with_contrast(system_accent_srgb, theme,
165	        increased_contrast, &tokens);
166	    tokens.accent = accent;
167	    tokens.selection_edge = accent;
168	    tokens.focus_ring = accent;
169	    tokens.selection_fill = ui_blend_opaque(tokens.panel, accent,
170	        increased_contrast ? 20U : 14U);
171	    return tokens;
172	}
