296	bool ui_tree_add(ui_tree *tree, const ui_node_spec *spec)
297	{
298	    if (tree == NULL || spec == NULL || tree->text_bytes_used > UI_TEXT_TOTAL_MAX_BYTES ||
299	        tree->laid_out || tree->count >= UI_MAX_NODES ||
300	        spec->id == 0U || spec->axis > UI_AXIS_VERTICAL ||
301	        spec->icon >= UI_ICON_COUNT ||
302	        spec->preferred_width > RASTER_TILE_MAX_AXIS ||
303	        spec->preferred_height > RASTER_TILE_MAX_AXIS ||
304	        spec->padding > RASTER_TILE_MAX_AXIS || spec->gap > RASTER_TILE_MAX_AXIS ||
305	        (spec->role < UI_ROLE_NONE || spec->role > UI_ROLE_STATUS) ||
306	        spec->label_len > UI_TEXT_TOTAL_MAX_BYTES || spec->value_len > UI_TEXT_TOTAL_MAX_BYTES ||
307	        spec->label_len > UI_TEXT_TOTAL_MAX_BYTES - tree->text_bytes_used ||
308	        spec->value_len > UI_TEXT_TOTAL_MAX_BYTES - tree->text_bytes_used - spec->label_len ||
309	        !ui_utf8_valid(spec->label, spec->label_len) ||
310	        !ui_utf8_valid(spec->value, spec->value_len) ||
311	        ui_index(tree, spec->id) != UI_NO_NODE) {
312	        return false;
313	    }
314	    uint16_t parent = UI_NO_NODE;
315	    if (tree->count == 0U) {
316	        if (spec->id != UI_ROOT_ID || spec->parent_id != 0U) return false;
317	    } else {
318	        parent = ui_index(tree, spec->parent_id);
319	        if (parent == UI_NO_NODE || tree->nodes[parent].child_count == UINT16_MAX) return false;
320	    }
321	    uint16_t added = (uint16_t)tree->count;
322	    ui_node *new_node = &tree->nodes[added];
323	    size_t label_preview_len = spec->label_len < UI_TEXT_MAX_BYTES - 1U ?
324	        spec->label_len : UI_TEXT_MAX_BYTES - 1U;
325	    while (label_preview_len > 0U && spec->label_len > label_preview_len &&
326	           spec->label != NULL && (((uint8_t)spec->label[label_preview_len] & 0xc0U) == 0x80U))
327	        label_preview_len--;
328	    size_t value_preview_len = spec->value_len < UI_TEXT_MAX_BYTES - 1U ?
329	        spec->value_len : UI_TEXT_MAX_BYTES - 1U;
330	    while (value_preview_len > 0U && spec->value_len > value_preview_len &&
331	           spec->value != NULL && (((uint8_t)spec->value[value_preview_len] & 0xc0U) == 0x80U))
332	        value_preview_len--;
333	    size_t label_offset = tree->text_bytes_used;
334	    size_t value_offset = label_offset + spec->label_len;
335	    *new_node = (ui_node){.spec = *spec, .first_child = UI_NO_NODE,
336	        .next_sibling = UI_NO_NODE, .occupied = true,
337	        .full_label_len = spec->label_len, .full_value_len = spec->value_len,
338	        .label_offset = label_offset, .value_offset = value_offset};
339	    new_node->spec.label = NULL;
340	    new_node->spec.value = NULL;
341	    new_node->spec.label_len = label_preview_len;
342	    new_node->spec.value_len = value_preview_len;
343	    new_node->spec.state &= ~(uint32_t)UI_STATE_FOCUSED;
344	    if (spec->label_len > 0U) memcpy(tree->text_storage + label_offset, spec->label, spec->label_len);
345	    if (spec->value_len > 0U) memcpy(tree->text_storage + value_offset, spec->value, spec->value_len);
346	    if (label_preview_len > 0U) memcpy(new_node->label, spec->label, label_preview_len);
347	    if (value_preview_len > 0U) memcpy(new_node->value, spec->value, value_preview_len);
348	    tree->text_bytes_used += spec->label_len + spec->value_len;
349	    tree->count++;
350	    if (parent != UI_NO_NODE) {
351	        ui_node *owner = &tree->nodes[parent];
352	        if (owner->first_child == UI_NO_NODE) owner->first_child = added;
353	        else {
354	            uint16_t last = owner->first_child;
355	            while (tree->nodes[last].next_sibling != UI_NO_NODE) last = tree->nodes[last].next_sibling;
356	            tree->nodes[last].next_sibling = added;
357	        }
358	        owner->child_count++;
359	    }
360	    return true;
361	}
