363	static bool ui_layout_node(ui_tree *tree, uint16_t index, ui_rect box, uint32_t depth)
364	{
365	    if (depth > UI_MAX_DEPTH) return false;
366	    ui_node *node = &tree->nodes[index];
367	    node->bounds = box;
368	    if (node->child_count == 0U) return true;
369	    uint32_t twice_padding = node->spec.padding * 2U;
370	    uint32_t inner_x = box.x + node->spec.padding;
371	    uint32_t inner_y = box.y + node->spec.padding;
372	    uint32_t inner_width = box.width > twice_padding ? box.width - twice_padding : 0U;
373	    uint32_t inner_height = box.height > twice_padding ? box.height - twice_padding : 0U;
374	    if (node->spec.axis == UI_AXIS_OVERLAY) {
375	        for (uint16_t child = node->first_child; child != UI_NO_NODE;
376	             child = tree->nodes[child].next_sibling) {
377	            ui_node *item = &tree->nodes[child];
378	            uint32_t width = item->spec.preferred_width == 0U ? inner_width : item->spec.preferred_width;
379	            uint32_t height = item->spec.preferred_height == 0U ? inner_height : item->spec.preferred_height;
380	            if (width > inner_width) width = inner_width;
381	            if (height > inner_height) height = inner_height;
382	            if (!ui_layout_node(tree, child, (ui_rect){inner_x, inner_y, width, height}, depth + 1U)) {
383	                return false;
384	            }
385	        }
386	        return true;
387	    }
388	    uint32_t main_extent = node->spec.axis == UI_AXIS_HORIZONTAL ? inner_width : inner_height;
389	    uint32_t cross_extent = node->spec.axis == UI_AXIS_HORIZONTAL ? inner_height : inner_width;
390	    uint32_t gaps = node->spec.gap * (uint32_t)(node->child_count - 1U);
391	    uint32_t fixed = 0U, flexible = 0U;
392	    for (uint16_t child = node->first_child; child != UI_NO_NODE; child = tree->nodes[child].next_sibling) {
393	        ui_node_spec *spec = &tree->nodes[child].spec;
394	        uint32_t wanted = node->spec.axis == UI_AXIS_HORIZONTAL ? spec->preferred_width : spec->preferred_height;
395	        if (wanted == 0U) flexible++;
396	        else if (UINT32_MAX - fixed < wanted) return false;
397	        else fixed += wanted;
398	    }
399	    uint32_t bounded_gaps = gaps > main_extent ? main_extent : gaps;
400	    uint32_t available = main_extent - bounded_gaps;
401	    uint32_t flex_extent = available > fixed ? available - fixed : 0U;
402	    uint32_t remaining = main_extent;
403	    uint32_t cursor = node->spec.axis == UI_AXIS_HORIZONTAL ? inner_x : inner_y;
404	    uint16_t child = node->first_child;
405	    while (child != UI_NO_NODE) {
406	        if (child != node->first_child && remaining > 0U) {
407	            uint32_t gap = node->spec.gap < remaining ? node->spec.gap : remaining;
408	            cursor += gap;
409	            remaining -= gap;
410	        }
411	        ui_node *item = &tree->nodes[child];
412	        uint32_t preferred = node->spec.axis == UI_AXIS_HORIZONTAL ? item->spec.preferred_width : item->spec.preferred_height;
413	        uint32_t extent = preferred == 0U ? (flexible == 0U ? 0U : flex_extent / flexible) : preferred;
414	        if (extent > remaining) extent = remaining;
415	        if (preferred == 0U && flexible > 0U) {
416	            flex_extent = flex_extent > extent ? flex_extent - extent : 0U;
417	            flexible--;
418	        }
419	        uint32_t cross = node->spec.axis == UI_AXIS_HORIZONTAL ? item->spec.preferred_height : item->spec.preferred_width;
420	        if (cross == 0U || cross > cross_extent) cross = cross_extent;
421	        ui_rect child_box = node->spec.axis == UI_AXIS_HORIZONTAL
422	            ? (ui_rect){cursor, inner_y, extent, cross}
423	            : (ui_rect){inner_x, cursor, cross, extent};
424	        if (!ui_layout_node(tree, child, child_box, depth + 1U)) return false;
425	        cursor += extent;
426	        remaining -= extent;
427	        child = item->next_sibling;
428	    }
429	    return true;
430	}
