432	bool ui_tree_layout(ui_tree *tree, uint32_t width, uint32_t height)
433	{
434	    if (tree == NULL || tree->count == 0U || tree->count > UI_MAX_NODES ||
435	        tree->laid_out || width == 0U || height == 0U ||
436	        width > RASTER_TILE_MAX_AXIS || height > RASTER_TILE_MAX_AXIS) return false;
437	    if (!ui_layout_node(tree, 0U, (ui_rect){0U, 0U, width, height}, 0U)) return false;
438	    tree->laid_out = true;
439	    return true;
440	}
