442	static bool ui_render_node(const ui_node *node, raster_tile *tile)
443	{
444	    char svg[UI_SVG_CAPACITY];
445	    uint32_t rgba = node->spec.color;
446	    int length = snprintf(svg, sizeof(svg),
447	        "<svg width=\"4\" height=\"4\"><rect width=\"4\" height=\"4\" fill=\"#%06x\"/></svg>",
448	        (rgba >> 8U) & 0xffffffU);
449	    if (length < 0 || (size_t)length >= sizeof(svg)) return false;
450	    svg_shape_document document = {0};
451	    svg_shape_diagnostic diagnostic = {0};
452	    base_bytes bytes = {(const uint8_t *)svg, (size_t)length};
453	    svg_shape_media_providers providers = svg_app_media_providers();
454	    if (svg_shape_decode_with_media(bytes, &providers, &document,
455	            &diagnostic) != SVG_SHAPE_ERROR_NONE) return false;
456	    raster_tile sample = {0};
457	    bool okay = raster_shape_render(&document, &sample, &diagnostic);
458	    svg_shape_document_destroy(&document);
459	    if (!okay) return false;
460	    size_t sample_at = ((size_t)(sample.height / 2U) * sample.width + sample.width / 2U) * 4U;
461	    const uint8_t *paint = sample.rgba + sample_at;
462	    uint32_t x_end = node->bounds.x + node->bounds.width;
463	    uint32_t y_end = node->bounds.y + node->bounds.height;
464	    if (x_end > tile->width) x_end = tile->width;
465	    if (y_end > tile->height) y_end = tile->height;
466	    for (uint32_t y = node->bounds.y; y < y_end; y++) {
467	        for (uint32_t x = node->bounds.x; x < x_end; x++) {
468	            size_t at = ((size_t)y * tile->width + x) * 4U;
469	            uint32_t alpha = paint[3];
470	            uint32_t inverse = 255U - alpha;
471	            for (size_t channel = 0U; channel < 3U; channel++) {
472	                uint32_t value = (uint32_t)paint[channel] * alpha +
473	                    (uint32_t)tile->rgba[at + channel] * inverse;
474	                tile->rgba[at + channel] = (uint8_t)((value + 127U) / 255U);
475	            }
476	            tile->rgba[at + 3U] = 255U;
477	        }
478	    }
479	    raster_tile_destroy(&sample);
480	    return true;
481	}
