483	static bool ui_render_focus_ring(const ui_node *node, uint32_t accent, raster_tile *tile)
484	{
485	    if (node->bounds.width < 2U || node->bounds.height < 2U) return true;
486	    ui_node edge = *node;
487	    edge.spec.color = accent;
488	    edge.bounds.height = 1U;
489	    if (!ui_render_node(&edge, tile)) return false;
490	    edge.bounds.y = node->bounds.y + node->bounds.height - 1U;
491	    if (!ui_render_node(&edge, tile)) return false;
492	    edge.bounds = (ui_rect){node->bounds.x, node->bounds.y + 1U, 1U, node->bounds.height - 2U};
493	    if (!ui_render_node(&edge, tile)) return false;
494	    edge.bounds.x = node->bounds.x + node->bounds.width - 1U;
495	    return ui_render_node(&edge, tile);
496	}
