498	bool ui_tree_render(const ui_tree *tree, raster_tile *out_tile)
499	{
500	    if (tree == NULL || out_tile == NULL || !tree->laid_out || tree->count == 0U ||
501	        tree->count > UI_MAX_NODES) return false;
502	    *out_tile = (raster_tile){0};
503	    const ui_rect root = tree->nodes[0].bounds;
504	    if (!raster_tile_create(root.width, root.height, out_tile)) return false;
505	    for (size_t index = 0U; index < tree->count; index++) {
506	        const ui_node *node = &tree->nodes[index];
507	        if ((node->spec.color & 255U) == 0U) continue;
508	        if (!ui_render_node(node, out_tile) ||
509	            ((node->spec.state & UI_STATE_FOCUSED) != 0U &&
510	        !ui_render_focus_ring(node, tree->tokens.focus_ring, out_tile))) {
511	            raster_tile_destroy(out_tile);
512	            return false;
513	        }
514	    }
515	    return true;
516	}
