531	bool ui_focus_next(ui_tree *tree, bool reverse)
532	{
533	    if (tree == NULL || tree->count < 2U) return false;
534	    uint16_t current = ui_index(tree, tree->focused_id);
535	    size_t start = current == UI_NO_NODE ? (reverse ? tree->count - 1U : 0U) : (size_t)current;
536	    for (size_t step = 1U; step <= tree->count; step++) {
537	        size_t candidate;
538	        if (reverse) candidate = (start + tree->count - (step % tree->count)) % tree->count;
539	        else candidate = (start + step) % tree->count;
540	        if (ui_node_focusable(&tree->nodes[candidate])) {
541	            for (size_t index = 0U; index < tree->count; index++) {
542	                tree->nodes[index].spec.state &= ~(uint32_t)UI_STATE_FOCUSED;
543	            }
544	            tree->nodes[candidate].spec.state |= UI_STATE_FOCUSED;
545	            tree->focused_id = tree->nodes[candidate].spec.id;
546	            return true;
547	        }
548	    }
549	    return false;
550	}
