552	bool ui_semantics_snapshot_build(const ui_tree *tree, ui_semantics_snapshot *out_snapshot)
553	{
554	    if (tree == NULL || out_snapshot == NULL || tree->count > UI_MAX_NODES ||
555	        tree->text_bytes_used > UI_TEXT_TOTAL_MAX_BYTES) return false;
556	    memset(out_snapshot, 0, sizeof(*out_snapshot));
557	    for (size_t index = 0U; index < tree->count; index++) {
558	        const ui_node *source = &tree->nodes[index];
559	        if (!source->occupied || source->spec.label_len > UI_TEXT_MAX_BYTES ||
560	            source->spec.value_len > UI_TEXT_MAX_BYTES ||
561	            source->full_label_len > UI_TEXT_TOTAL_MAX_BYTES ||
562	            source->full_value_len > UI_TEXT_TOTAL_MAX_BYTES ||
563	            source->label_offset > tree->text_bytes_used ||
564	            source->full_label_len > tree->text_bytes_used - source->label_offset ||
565	            source->value_offset > tree->text_bytes_used ||
566	            source->full_value_len > tree->text_bytes_used - source->value_offset) return false;
567	        ui_semantics_node *node = &out_snapshot->nodes[index];
568	        node->id = source->spec.id;
569	        node->parent_id = source->spec.parent_id;
570	        node->role = source->spec.role;
571	        node->state = source->spec.state;
572	        node->command_id = source->spec.command_id;
573	        node->label_len = source->spec.label_len;
574	        node->value_len = source->spec.value_len;
575	        node->label_full_len = source->full_label_len;
576	        node->value_full_len = source->full_value_len;
577	        node->frame = source->bounds;
578	        memcpy(node->label, source->label, node->label_len);
579	        memcpy(node->value, source->value, node->value_len);
580	        if (node->label_full_len > UI_TEXT_TOTAL_MAX_BYTES - out_snapshot->text_bytes_used ||
581	            node->value_full_len > UI_TEXT_TOTAL_MAX_BYTES - out_snapshot->text_bytes_used -
582	                node->label_full_len) return false;
583	        node->label_offset = out_snapshot->text_bytes_used;
584	        if (node->label_full_len > 0U)
585	            memcpy(out_snapshot->text_storage + node->label_offset,
586	                tree->text_storage + source->label_offset, node->label_full_len);
587	        node->value_offset = node->label_offset + node->label_full_len;
588	        if (node->value_full_len > 0U)
589	            memcpy(out_snapshot->text_storage + node->value_offset,
590	                tree->text_storage + source->value_offset, node->value_full_len);
591	        out_snapshot->text_bytes_used += node->label_full_len + node->value_full_len;
592	    }
593	    out_snapshot->count = tree->count;
594	    return true;
595	}
