597	bool ui_semantics_text(const ui_semantics_snapshot *snapshot,
598	                       const ui_semantics_node *node, bool value,
599	                       const char **out_text, size_t *out_length)
600	{
601	    if (snapshot == NULL || node == NULL || out_text == NULL || out_length == NULL ||
602	        snapshot->count > UI_MAX_NODES || snapshot->text_bytes_used > UI_TEXT_TOTAL_MAX_BYTES)
603	        return false;
604	    size_t offset = value ? node->value_offset : node->label_offset;
605	    size_t length = value ? node->value_full_len : node->label_full_len;
