   266	static bool ui_utf8_valid(const char *text, size_t length)
   267	{
   268	    if (length > 0U && text == NULL) return false;
   269	    size_t index = 0U;
   270	    while (index < length) {
   271	        uint8_t first = (uint8_t)text[index];
   272	        size_t continuation = 0U;
   273	        uint8_t lower = 0x80U, upper = 0xbfU;
   274	        if (first < 0x80U) { index++; continue; }
   275	        if (first >= 0xc2U && first <= 0xdfU) continuation = 1U;
   276	        else if (first == 0xe0U) { continuation = 2U; lower = 0xa0U; }
   277	        else if (first >= 0xe1U && first <= 0xecU) continuation = 2U;
   278	        else if (first == 0xedU) { continuation = 2U; upper = 0x9fU; }
   279	        else if (first >= 0xeeU && first <= 0xefU) continuation = 2U;
   280	        else if (first == 0xf0U) { continuation = 3U; lower = 0x90U; }
   281	        else if (first >= 0xf1U && first <= 0xf3U) continuation = 3U;
   282	        else if (first == 0xf4U) { continuation = 3U; upper = 0x8fU; }
   283	        else return false;
   284	        if (continuation > length - index - 1U) return false;
   285	        uint8_t second = (uint8_t)text[index + 1U];
   286	        if (second < lower || second > upper) return false;
   287	        for (size_t offset = 2U; offset <= continuation; offset++) {
   288	            uint8_t byte = (uint8_t)text[index + offset];
   289	            if (byte < 0x80U || byte > 0xbfU) return false;
   290	        }
   291	        index += continuation + 1U;
   292	    }
   293	    return true;
   294	}
